(()=>{
const $=id=>document.getElementById(id),key='thanda-garam-baristas-v1';let data={active:null,profiles:[]},persistent=true,pending=null;
try{const raw=JSON.parse(localStorage.getItem(key)||'null');if(raw&&Array.isArray(raw.profiles)){data.profiles=raw.profiles.filter(p=>typeof p.id==='string'&&typeof p.name==='string'&&Number.isInteger(p.right)&&p.right>=0&&Number.isInteger(p.wrong)&&p.wrong>=0);data.active=data.profiles.some(p=>p.id===raw.active)?raw.active:null;}}catch{persistent=false;}
function save(){try{localStorage.setItem(key,JSON.stringify(data));}catch{persistent=false;}render();}
function current(){return data.profiles.find(p=>p.id===data.active)||null;}
function render(){const busy=Boolean(window.cafeRoundActive?.());const active=current();$('profile-status').textContent=busy?'Your cup is on the clock. Finish it before switching baristas.':active?'At the counter: '+active.name+'. Choose a saved name or add another.':'Enter your name to start your barista scorebook.';$('barista-name').disabled=busy;$('profile-form').querySelector('button').disabled=busy;$('storage-note').textContent=persistent?'Saved in this browser on this device. Clearing browser data removes these scores. Only served drinks and timeouts count.':'Browser storage is unavailable. Scores are kept only until this page closes.';const list=$('score-list');list.replaceChildren();if(!data.profiles.length){const p=document.createElement('p');p.className='score-empty';p.textContent='Your first cup starts the story.';list.append(p);return;}const table=document.createElement('table');table.innerHTML='<thead><tr><th>Barista</th><th>Right</th><th>Wrong</th><th></th></tr></thead><tbody></tbody>';for(const p of data.profiles){const row=document.createElement('tr');for(const val of [p.name+(p.id===data.active?' ✓':''),p.right,p.wrong]){const td=document.createElement('td');td.textContent=val;row.append(td);}const td=document.createElement('td'),button=document.createElement('button');button.textContent='Play';button.disabled=busy;button.setAttribute('aria-label','Play as '+p.name);button.onclick=()=>select(p.id);td.append(button);row.append(td);table.tBodies[0].append(row);}list.append(table);}
function select(id){data.active=id;save();$('scores-dialog').close();const callback=pending;pending=null;if(callback)callback();}
$('profile-form').onsubmit=e=>{e.preventDefault();if(window.cafeRoundActive?.())return;const name=$('barista-name').value.trim().replace(/\s+/g,' ').slice(0,30);if(!name){$('barista-name').setCustomValidity('Enter your barista name.');$('barista-name').reportValidity();return;}let profile=data.profiles.find(p=>p.name.toLocaleLowerCase()===name.toLocaleLowerCase());if(!profile){profile={id:crypto.randomUUID(),name,right:0,wrong:0};data.profiles.push(profile);}select(profile.id);};$('barista-name').oninput=()=>$('barista-name').setCustomValidity('');
$('scores-open').onclick=()=>{render();$('scores-dialog').showModal();};$('scores-close').onclick=()=>{pending=null;$('scores-dialog').close();};$('scores-dialog').addEventListener('cancel',()=>{pending=null;});
window.Baristas={current,require(callback){if(current()){callback();return;}pending=callback;render();$('scores-dialog').showModal();$('barista-name').focus();},record(id,ok){const profile=data.profiles.find(p=>p.id===id);if(!profile)return;profile[ok?'right':'wrong']++;save();window.CafeLeaderboard?.record(profile,ok);},refresh:render};render();
})();
